177	\begin{theorem}[Quantum soundness of the simultaneous classical low individual degree test]\label{lem:ld-soundness}
178		\lean{MIPStarRE.QPBT.deltaLd, MIPStarRE.QPBT.exists_ld_soundness}
179		\leanok
