1235	% the number m of summands unquantified (m >= 1 is needed for the level max_j ell_j to
1236	% have an index) and begins its induction at level 1; the level-zero base case is supplied
1237	% here, since def:cl-func admits 0-level functions and all ell_j may be 0.
1238	\begin{lemma}[Direct sums of conditionally linear functions]\label{lem:cl-func-prod}
1239		\lean{MIPStarRE.QPBT.IsCondLinear.directSum}
1240		\leanok
1241		\uses{def:cl-func, def:register-subspace}
1242		Let $m \ge 1$ be an integer and let $V^{(1)}, V^{(2)}, \dots, V^{(m)}$ be register subspaces of $V$ such that $V = \bigoplus_{j=1}^m V^{(j)}$. Suppose that, for each $j \in \{1, 2, \dots, m\}$, $L^{(j)}$ is an $\ell_j$-level conditionally linear function on $V^{(j)}$. Then the direct sum $L = \bigoplus_{j=1}^m L^{(j)}$, defined by
1243		\[
1244			L(x) = \sum_{j=1}^m L^{(j)}(x^{(j)})
1245		\]
1246		for all $x = \sum_{j=1}^m x^{(j)} \in \bigoplus_{j=1}^m V^{(j)}$, is an $\ell$-level CL function on $V$ for $\ell = \max_j \{\ell_j\}$; the maximum exists since $m \ge 1$.
1247		With zero-based indices, the summand labelled $r\in\{0,\ldots,m-1\}$
1248		corresponds to the paper's summand $j=r+1$.
1249	\end{lemma}
1250	\begin{proof}
1251		\leanok
1252		\uses{def:cl-func, lem:cl-func-prod-same-level}
1253		Since an $\ell$-level CL function is also $k$-level conditionally linear for all $k \ge \ell$, it suffices to prove the claim when $\ell_j = \ell$ for all $j$. Proceed by induction on $\ell$. For $\ell = 0$ every $L^{(j)}$ is the zero function on $V^{(j)}$, so $L$ is the zero function on $V$, which is the unique $0$-level CL function on $V$ (Definition~\ref{def:cl-func}). For the inductive step with $\ell \ge 1$, decompose each $L^{(j)}$ into its first-level linear part $L^{(j)}_1$ on $V^{(j)}_1$ and its family of $(\ell-1)$-level remainders $L^{(j)}_{>1,\,v_j}$ on $V^{(j)}_{>1}$. The direct sums of the first-level parts define a linear map on $V_1 = \bigoplus_j V^{(j)}_1$, and, for each prefix value $v = \sum_j v_j$, the direct sums of the remainders are $(\ell-1)$-level conditionally linear on $V_{>1} = \bigoplus_j V^{(j)}_{>1}$ by the induction hypothesis. This exhibits $L$ in the form required by Definition~\ref{def:cl-func}.
1254	\end{proof}
